codeExamples.code:
-- Low-cardinality columns in a warehouse fact/dim table
CREATE BITMAP INDEX bx_sales_region ON sales (region);
CREATE BITMAP INDEX bx_sales_channel ON sales (channel);
CREATE BITMAP INDEX bx_sales_status ON sales (status);

-- The optimizer ANDs the bitmaps to satisfy multiple predicates cheaply
SELECT COUNT(*)
FROM sales
WHERE region = 'APAC'
  AND channel = 'ONLINE'
  AND status = 'COMPLETED';

-- Cluster files so per-file min/max stats become tight for these columns
OPTIMIZE events
ZORDER BY (user_id, event_type);

-- Bloom filter index for high-cardinality equality lookups (point queries)
CREATE BLOOMFILTER INDEX
ON TABLE events
FOR COLUMNS(user_id OPTIONS (fpp = 0.01, numItems = 50000000));

-- Point query now skips files whose bloom filter says user_id is absent
SELECT * FROM events WHERE user_id = 987654321;
